#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;

long long modularExponentiation(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    long long totalCells = n * m;
    if (totalCells % 2 == 1) {
        cout << modularExponentiation(r - l + 1, totalCells) << "\n";
        return 0;
    }

    long long evenCount = r / 2 - (l - 1) / 2;
    long long oddCount = (r - l + 1) - evenCount;

    long long total = (modularExponentiation(evenCount + oddCount, totalCells) + modularExponentiation(evenCount - oddCount, totalCells)) % MOD;
    long long inv2 = modularExponentiation(2, MOD - 2);
    long long answer = (total * inv2) % MOD;

    cout << answer << "\n";

    return 0;
}
